bnr.css:
#ksBnr .kgw{position:relative;flex:none;width:390px;height:160px;overflow:hidden;background:#FCE9CF}
#ksBnr .kgw>*{position:absolute;display:block}
#ksBnr .kgw .bnr{left:0;top:0;width:390px;height:160px;object-fit:cover}
#ksBnr .kgw .kgSky{left:0;top:0;width:390px;height:160px}
#ksBnr .kgw .kgSun{left:300px;top:4px;width:58px;height:58px;animation:kbkgSun 80s linear infinite}
#ksBnr .kgw .kgCl{left:0;top:2px;width:780px;height:50px;background-size:390px 50px;background-repeat:repeat-x;animation:kbkgFlow 90s linear infinite}
#ksBnr .kgw .kgFar{left:0;top:58px;width:780px;height:70px;background-size:390px 70px;background-repeat:repeat-x;animation:kbkgFlow 48s linear infinite}
#ksBnr .kgw .kgMid{left:0;top:80px;width:780px;height:64px;background-size:390px 64px;background-repeat:repeat-x;animation:kbkgFlow 26s linear infinite}
#ksBnr .kgw .kgNear{left:0;top:114px;width:780px;height:48px;background-size:390px 48px;background-repeat:repeat-x;animation:kbkgFlow 13s linear infinite}
#ksBnr .kgw .kgFr{left:0;top:140px;width:780px;height:22px;background-size:390px 22px;background-repeat:repeat-x;animation:kbkgFlow 7s linear infinite}
#ksBnr .kgw .kgBd{left:0;top:0;width:20px;height:12px}
#ksBnr .kgw .kgBd>img{position:absolute;display:block}
#ksBnr .kgw .kgBb{left:0;top:0;width:20px;height:12px}
#ksBnr .kgw .kgWg{left:5px;top:0;width:12px;height:8px;transform-origin:31% 86%;animation:kbkgWing .38s ease-in-out infinite alternate}
#ksBnr .kgw .kgBd.b1{animation:kbkgB1 22s linear infinite}
#ksBnr .kgw .kgBd.b2{animation:kbkgB2 22s linear -9s infinite}
#ksBnr .kgw .kgH{left:104px;top:55.5px;width:112px;height:89.6px}
#ksBnr .kgw .kgSh{position:absolute;left:15.68px;top:88.26px;width:67.2px;height:6.72px;border-radius:50%;background:rgba(60,40,20,.26);animation:kbkgShd 0.68s ease-in-out infinite}
#ksBnr .kgw .kgB{position:absolute;left:0;top:0;width:112px;height:89.6px;animation:kbkgBob 0.68s ease-in-out infinite}
#ksBnr .kgw .kgB>img{position:absolute;display:block}
#ksBnr .kgw .kgBody{left:0;top:0;width:112px;height:89.6px}
#ksBnr .kgw .kgT{left:-0.56px;top:39.2px;width:26.88px;height:38.08px;transform-origin:21.28px 4.48px;animation:kbkgTail 1.36s ease-in-out infinite alternate}
#ksBnr .kgw .kgL{width:20.16px;height:47.04px;transform-origin:10.08px 7.84px}
#ksBnr .kgw .kgL.hn,#ksBnr .kgw .kgL.hf{height:49.28px}
#ksBnr .kgw .kgL.fn{left:57.12px;top:49.28px;animation:kbkgLegA 0.68s ease-in-out infinite}
#ksBnr .kgw .kgL.hn{left:18.48px;top:47.04px;animation:kbkgLegB 0.68s ease-in-out infinite}
#ksBnr .kgw .kgL.ff{left:60.48px;top:48.16px;animation:kbkgLegB 0.68s ease-in-out infinite}
#ksBnr .kgw .kgL.hf{left:22.4px;top:45.92px;animation:kbkgLegA 0.68s ease-in-out infinite}
#ksBnr .kgw .kgPin.p0{left:63.6px;top:53.52px;width:7.2px;height:7.2px}
#ksBnr .kgw .kgPin.p1{left:24.96px;top:51.28px;width:7.2px;height:7.2px}
#ksBnr .kgw .kgPin.p2{left:17.12px;top:40.08px;width:7.2px;height:7.2px}
@keyframes kbkgFlow{0%{transform:translateX(0)}100%{transform:translateX(-390px)}}
@keyframes kbkgSun{0%{transform:rotate(0)}100%{transform:rotate(360deg)}}
@keyframes kbkgLegA{0%{transform:rotate(28deg)}50%{transform:rotate(-30deg)}100%{transform:rotate(28deg)}}
@keyframes kbkgLegB{0%{transform:rotate(-30deg)}50%{transform:rotate(28deg)}100%{transform:rotate(-30deg)}}
@keyframes kbkgBob{0%{transform:translateY(4.04px)}25%{transform:translateY(0)}50%{transform:translateY(4.62px)}75%{transform:translateY(0)}100%{transform:translateY(4.04px)}}
@keyframes kbkgShd{0%{transform:scale(1);opacity:1}25%{transform:scale(.92);opacity:.85}50%{transform:scale(1);opacity:1}75%{transform:scale(.92);opacity:.85}100%{transform:scale(1);opacity:1}}
@keyframes kbkgTail{0%{transform:rotate(-14deg)}100%{transform:rotate(12deg)}}
@keyframes kbkgWing{0%{transform:scaleY(1)}100%{transform:scaleY(-.7)}}
@keyframes kbkgB1{0%{transform:translate(-30px,30px)}30%{transform:translate(110px,18px)}60%{transform:translate(250px,28px)}100%{transform:translate(420px,14px)}}
@keyframes kbkgB2{0%{transform:translate(-30px,46px) scale(.8)}35%{transform:translate(130px,36px) scale(.8)}70%{transform:translate(280px,44px) scale(.8)}100%{transform:translate(420px,34px) scale(.8)}}
@media (prefers-reduced-motion:reduce){#ksBnr .kgw>:not(.bnr){display:none!important}}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
#ksBnr.calm .kgw>:not(.bnr){display:none!important}

push.css:
.fxs .kg{--pushA:#D8473A;--pushB:#6E2A20;--pushC:#2B7F79;--rim:#F7D35A;--rimD:#6E2A20}
.fxs .push.kg{--pr:14px;background:none;border-radius:14px;box-shadow:none;filter:drop-shadow(0 8px 0 rgba(90,46,30,.35)) drop-shadow(0 16px 20px rgba(0,0,0,.3))}
.fxs .push.kg span{font:400 42px/1 "Zen Kurenaido",sans-serif;letter-spacing:.08em;color:#FFF4E0;text-shadow:1.5px 2px 0 #8E2A22,0 0 8px rgba(255,244,224,.35)}
.fxs .push.kg::after{inset:-20px;border-radius:30px;border-color:rgba(247,211,90,.9)}
.fxs .kg .kgf{position:absolute;left:-10px;top:-12px;width:228px;height:128px;pointer-events:none;font-style:normal;z-index:-1}
.fxs .kg .kgf svg{display:block;width:228px;height:128px;overflow:visible}
.fxs .kg .kgd{position:absolute;left:-40px;top:-70px;width:280px;height:210px;pointer-events:none;z-index:3;font-style:normal}
.fxs .kg .kgd svg{display:block;width:280px;height:210px;overflow:visible}
.fxs .kg .kgbo{transform-box:fill-box;transform-origin:50% 50%;animation:fxkgBo 2.8s ease-in-out infinite alternate}
@keyframes fxkgBo{from{transform:translateY(-4px) rotate(-12deg)}to{transform:translateY(4px) rotate(12deg)}}
.fxs .pshadow.kg{width:220px}
.fxs .tap.kg{font-family:"Zen Kurenaido",sans-serif;font-weight:400;color:#FFF4E0;letter-spacing:.14em;text-shadow:0 2px 0 #8E2A22,0 0 10px rgba(255,244,224,.5)}
.fxs .pressed.kg{border-radius:14px;background:#D8473A;box-shadow:4px 4.5px 0 #FFF4E0,8px 9px 0 #2B7F79;animation-name:fxkgPress,fxfxH}
@keyframes fxkgPress{0%{transform:scale(1)}22%{transform:scale(.9) rotate(-2deg)}45%{transform:scale(1.07) rotate(1deg)}100%{transform:scale(1.45);opacity:0}}
@media (prefers-reduced-motion:reduce){.fxs .kg .kgbo{animation:none}
.fxs .clips.kg{display:none}}
.fxs .clips.kg{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
.fxs .clips.kg i{position:absolute;opacity:0;left:calc(var(--z) / -2);top:calc(var(--z) / -2);width:var(--z);height:var(--z);animation:fxkgFly 1.5s cubic-bezier(.2,.6,.4,1) calc(var(--d) + .1s) both;background:center/contain no-repeat}
